using System;

IPricePolicy policy = new MeasuredPrice(new PercentageDiscount(0.10m));
Console.WriteLine(policy.Calculate(200m)); // 180

public interface IPricePolicy { decimal Calculate(decimal subtotal); }
public sealed class PercentageDiscount(decimal rate) : IPricePolicy
{
    public decimal Calculate(decimal subtotal)
    {
        if (rate is < 0m or > 1m || subtotal < 0m)
            throw new ArgumentOutOfRangeException();
        return subtotal * (1m - rate);
    }
}
public sealed class MeasuredPrice(IPricePolicy inner) : IPricePolicy
{
    public decimal Calculate(decimal subtotal)
    {
        var started = System.Diagnostics.Stopwatch.StartNew();
        try { return inner.Calculate(subtotal); }
        finally { Console.WriteLine($"Süre: {started.Elapsed}"); }
    }
}

