public sealed class BatchOptions { public int Limit { get; set; } }
public sealed class BatchJob(IOptions<BatchOptions> options)
{
    public Task RunAsync(CancellationToken ct) =>
        Task.Delay(options.Value.Limit, ct);
}
public sealed class Worker(IServiceScopeFactory scopes) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await using var scope = scopes.CreateAsyncScope();
            await scope.ServiceProvider.GetRequiredService<BatchJob>()
                .RunAsync(stoppingToken);
            await Task.Delay(TimeSpan.FromSeconds(1), stoppingToken);
        }
    }
}

