public sealed class Order(Guid id)
{
    public Guid Id { get; } = id;
    public decimal Total { get; private set; }
    public bool IsConfirmed { get; private set; }
    public void Add(int quantity, decimal unitPrice)
    {
        if (IsConfirmed) throw new InvalidOperationException("Sipariş kapandı");
        if (quantity <= 0 || unitPrice < 0m)
            throw new ArgumentOutOfRangeException();
        Total += quantity * unitPrice;
    }
    public void Confirm()
    {
        if (IsConfirmed || Total <= 0m)
            throw new InvalidOperationException("Onaylanamaz");
        IsConfirmed = true;
    }
}
