using System.Security.Claims;
using Microsoft.AspNetCore.Authorization;

public sealed record OrderResource(Guid Id, string OwnerId);
public sealed class OwnOrderRequirement : IAuthorizationRequirement { }
public sealed class OwnOrderHandler
    : AuthorizationHandler<OwnOrderRequirement, OrderResource>
{
    protected override Task HandleRequirementAsync(
        AuthorizationHandlerContext context,
        OwnOrderRequirement requirement, OrderResource resource)
    {
        string? userId = context.User.FindFirstValue(ClaimTypes.NameIdentifier);
        if (context.User.Identity?.IsAuthenticated == true &&
            userId is not null && userId == resource.OwnerId)
            context.Succeed(requirement);
        return Task.CompletedTask;
    }
}
