public static class PlaceOrder
{
    public static async Task<Guid> ExecuteAsync(
        MessagingDb db, CancellationToken ct)
    {
        var orderId = Guid.NewGuid();
        db.Orders.Add(new MessageOrder { Id = orderId });
        db.Outbox.Add(new OutboxMessage
        {
            Id = Guid.NewGuid(),
            Payload = JsonSerializer.Serialize(new { OrderId = orderId })
        });
        await db.SaveChangesAsync(ct); // Aynı DB transaction'ında iki kayıt.
        return orderId;
    }
