// .NET konsol projesi; channel yalnızca süreç içindedir.
using System.Threading.Channels;

var queue = Channel.CreateBounded<int>(new BoundedChannelOptions(2)
{
    FullMode = BoundedChannelFullMode.Wait,
    SingleWriter = true,
    SingleReader = true
});
using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(5));
var producer = ProduceAsync(queue.Writer, timeout.Token);
var consumer = ConsumeAsync(queue.Reader, timeout.Token);
await Task.WhenAll(producer, consumer);

static async Task ProduceAsync(ChannelWriter<int> writer, CancellationToken ct)
{
    Exception? failure = null;
    try
    {
        for (int i = 0; i < 10; i++) await writer.WriteAsync(i, ct);
    }
    catch (Exception ex) { failure = ex; throw; }
    finally { writer.TryComplete(failure); }
}
static async Task ConsumeAsync(ChannelReader<int> reader, CancellationToken ct)
{
    await foreach (int item in reader.ReadAllAsync(ct))
    {
        await Task.Delay(50, ct);
        Console.WriteLine(item);
    }
}

